import { Token } from "cdktn";
import { ITerraformDependable } from "cdktn";
import { Construct } from "constructs";
// Generated by `cdktn get` (cdktf.json terraformProviders); not in Git
import { BuildDefinition } from "../../.gen/providers/azuredevops/build-definition";
import { DataAzuredevopsAgentQueue } from "../../.gen/providers/azuredevops/data-azuredevops-agent-queue";
import { DataAzuredevopsProject } from "../../.gen/providers/azuredevops/data-azuredevops-project";
import { DataAzuredevopsServiceendpointGithub } from "../../.gen/providers/azuredevops/data-azuredevops-serviceendpoint-github";
import { PipelineAuthorization } from "../../.gen/providers/azuredevops/pipeline-authorization";
import { AzuredevopsProvider } from "../../.gen/providers/azuredevops/provider";
import { idPart } from "../../utils/naming";

export interface AzureDevOpsPipelineConfig {
  /**
   * Construct ID key (Terraform address). Defaults to `name`. To rename
   * the resource without replacing it in state, set this to the old value.
   */
  key?: string;
  /** Pipeline name */
  name: string;
  /** Azure DevOps project name */
  project: string;
  /** GitHub service connection of the project (looked up by name) */
  githubServiceConnectionName: string;
  /** GitHub repository, "<owner>/<name>" */
  repository: string;
  /** Build definition in the repository */
  ymlPath: string;
  /** Branches whose pushes start the pipeline (exact names) */
  branches: string[];
  /** Agent pool of the pipeline (the Managed DevOps Pool) */
  agentPoolName: string;
  /** Plain-text pipeline variables (values from the infrastructure) */
  variables: Record<string, string>;
}

export interface AzureDevOpsPipelineOutput {
  pipeline: BuildDefinition;
}

/**
 * Azure Pipelines YAML pipeline for a GitHub repository, with its
 * variables, triggered by pushes to the given branches and permitted to use
 * the agent pool and the GitHub service connection.
 *
 * `poolDependencies`: the resource that registers the agent pool in the
 * project (Managed DevOps Pool); the queue is looked up after it.
 */
export function createAzureDevOpsPipeline(
  scope: Construct,
  provider: AzuredevopsProvider,
  config: AzureDevOpsPipelineConfig,
  poolDependencies: ITerraformDependable[],
): AzureDevOpsPipelineOutput {
  const id = idPart(config.key ?? config.name);

  const project = new DataAzuredevopsProject(scope, `ado-project-${id}`, {
    provider,
    name: config.project,
  });

  const github = new DataAzuredevopsServiceendpointGithub(scope, `ado-github-${id}`, {
    provider,
    projectId: project.id,
    serviceEndpointName: config.githubServiceConnectionName,
  });

  const queue = new DataAzuredevopsAgentQueue(scope, `ado-queue-${id}`, {
    provider,
    projectId: project.id,
    name: config.agentPoolName,
    dependsOn: poolDependencies,
  });

  const pipeline = new BuildDefinition(scope, `ado-pipeline-${id}`, {
    provider,
    projectId: project.id,
    name: config.name,
    agentPoolName: config.agentPoolName,
    ciTrigger: {
      override: {
        batch: false,
        branchFilter: [{ include: config.branches }],
      },
    },
    repository: {
      repoType: "GitHub",
      repoId: config.repository,
      branchName: `refs/heads/${config.branches[0]}`,
      ymlPath: config.ymlPath,
      serviceConnectionId: github.id,
    },
    variable: Object.entries(config.variables).map(([name, value]) => ({
      name,
      value,
    })),
  });

  const pipelineId = Token.asNumber(pipeline.id);
  new PipelineAuthorization(scope, `ado-auth-queue-${id}`, {
    provider,
    projectId: project.id,
    type: "queue",
    resourceId: queue.id,
    pipelineId,
  });
  new PipelineAuthorization(scope, `ado-auth-github-${id}`, {
    provider,
    projectId: project.id,
    type: "endpoint",
    resourceId: github.id,
    pipelineId,
  });

  return { pipeline };
}
